   async function loadAuditRows(){var q=E('auditSearch').value.trim(),rows=await raw('/api/audit'+(q?'?q='+encodeURIComponent(q):''));E('auditRows').innerHTML=table(rows,[{key:'action',label:'Action Performed',render:function(r){return'<b>'+esc(r.action.replace(/\./g,' '))+'</b>'}},{key:'performed_by',label:'Performed By'},{key:'performed_on',label:'Performed On'},{key:'performed_at',label:'Date / Time',render:function(r){return esc(new Date(r.performed_at).toLocaleString())}},{key:'resource_type',label:'Record Type'}])}
