   async function loadRequestRows(){var q=[],s=E('requestSearch').value.trim(),st=E('requestStatus').value;if(s)q.push('q='+encodeURIComponent(s));if(st)q.push('status='+encodeURIComponent(st));var rows=await raw('/api/system/request-logs'+(q.length?'?'+q.join('&'):''));E('requestRows').innerHTML=table(rows,[{key:'method',label:'Action',render:function(r){return'<b>'+esc(r.method)+'</b>'}},{key:'performed_by',label:'Performed By'},{key:'performed_on',label:'Performed On / Route'},{key:'status_code',label:'Status',render:function(r){return badge(String(r.status_code))}},{key:'performed_at',label:'Date / Time',render:function(r){return esc(new Date(r.performed_at).toLocaleString())}},{key:'duration_ms',label:'Duration',render:function(r){return esc(Number(r.duration_ms||0).toFixed(0))+' ms'}},{key:'request_id',label:'Request ID',render:function(r){return'<code>'+esc(r.request_id)+'</code>'}}])}
   async function loadErrorRows(){var q=['state='+encodeURIComponent(E('errorState').value)],s=E('errorSearch').value.trim();if(s)q.push('q='+encodeURIComponent(s));var rows=await raw('/api/system/errors?'+q.join('&'));E('errorRows').innerHTML=table(rows,[{key:'created_at',label:'Date / Time',render:function(r){return esc(new Date(r.created_at).toLocaleString())}},{key:'id',label:'Error Ref',render:function(r){return'<code>'+esc(r.id)+'</code>'}},{key:'path',label:'Route'},{key:'status_code',label:'Status'},{key:'error_code',label:'Code'},{key:'message'},{key:'resolved_at',label:'State',render:function(r){return badge(r.resolved_at?'resolved':'open')}}],function(r){return r.resolved_at?'<button class="mini" data-reopen-error="'+r.id+'">Reopen</button>':'<button class="mini primary" data-resolve-error="'+r.id+'">Resolve</button>'})}
   E('content').querySelectorAll('[data-system-tab]').forEach(function(b){b.onclick=async function(){E('content').querySelectorAll('.staff-tab').forEach(function(x){x.classList.toggle('active',x===b)});E('content').querySelectorAll('.system-pane').forEach(function(x){x.classList.add('hide')});E('system-'+b.dataset.systemTab).classList.remove('hide');if(b.dataset.systemTab==='audit')await loadAuditRows();if(b.dataset.systemTab==='changes')await loadChangeRows();if(b.dataset.systemTab==='requests')await loadRequestRows();if(b.dataset.systemTab==='errors')await loadErrorRows()}});
